export const TRICK_KEY = "lamprey";
export const TRICKS = ["oralclamp", "keratinrasp", "undulglide", "stonenest", "anadromous", "sevengill", "marinus"] as const;
export const HAPPY = ["densround", "inkround", "densdisk"] as const;
export type LampreyTrickKind = (typeof TRICKS)[number];
export type LampreyHappyKind = (typeof HAPPY)[number];
export type TrickAnim = "idle" | "walk" | "sit" | "sleep" | "talk" | "play";
export type TrickPhase = "go" | "hold" | "release" | "done";
export type HappyPhase = "go" | "done";

export type TrickFlags = {
  asleep?: boolean;
  hidden?: boolean;
  leaving?: boolean;
  cmd?: string;
  windowPlay?: boolean;
  card?: boolean;
};

export type LampreyTrick = {
  kind: LampreyTrickKind;
  phase: TrickPhase;
  t: number;
  x: number;
  lift: number;
  rot: number;
  anim: TrickAnim;
  facing: 1 | -1;
  fromX: number;
  abort?: boolean;
};

export type LampreyHappy = {
  kind: LampreyHappyKind;
  happy: true;
  phase: HappyPhase;
  t: number;
  x: number;
  lift: number;
  rot: number;
  anim: TrickAnim;
  facing: 1 | -1;
  fromX: number;
  abort?: boolean;
};

export const HAPPY_DUR = { densround: 1.70, inkround: 1.84, densdisk: 1.76 } as const;
export const MARINUS_HOLD = 11.2;
export const RELEASE_S = 1.18;
export const DUR = {
  marinus: MARINUS_HOLD + RELEASE_S,
  oralclamp: 2.48,
  keratinrasp: 2.56,
  undulglide: 2.42,
  stonenest: 2.38,
  anadromous: 2.40,
  sevengill: 2.44,
} as const;

export function canStart(state: TrickFlags | undefined) {
  if (!state) return false;
  if (state.asleep || state.hidden || state.leaving || state.windowPlay || state.card) return false;
  const cmd = String(state.cmd || "");
  if (cmd === "sleep" || cmd === "leave" || cmd === "hide" || cmd === "rest") return false;
  if (cmd === "seek" || cmd === "eat" || cmd === "play" || cmd === "talk" || cmd === "enter") return false;
  return true;
}

export function shouldAbort(state: TrickFlags | undefined) {
  if (!state) return true;
  if (state.asleep || state.hidden || state.leaving || state.windowPlay || state.card) return true;
  const cmd = String(state.cmd || "");
  return (
    cmd === "sleep" ||
    cmd === "leave" ||
    cmd === "hide" ||
    cmd === "rest" ||
    cmd === "seek" ||
    cmd === "eat" ||
    cmd === "play" ||
    cmd === "talk" ||
    cmd === "enter"
  );
}

export function nextTrickWait(justFinished: boolean, rand?: number, kind?: LampreyTrickKind | string) {
  const roll = rand == null ? Math.random() : rand;
  if (kind === "marinus") return 40 + roll * 26;
  if (kind === "anadromous" || kind === "stonenest" || kind === "oralclamp") return 12.8 + roll * 9.4;
  if (kind === "keratinrasp" || kind === "undulglide" || kind === "sevengill") return 11.6 + roll * 8.5;
  return justFinished ? 8.5 + roll * 8.4 : 4.4 + roll * 7.4;
}


